fn days_to_next_sunday(day: &str) -> i8 {
    // Map each day abbreviation to its 0-based index, where Sunday = 0
    let day_index = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => unreachable!("Input should always be a valid day abbreviation"),
    };

    // Calculate days until next Sunday: if day_index = 0 (Sunday), return 7; else 7 - day_index
    if day_index == 0 {
        7
    } else {
        7 - day_index
    }
}